// Some portions generated by Claude
import assert from 'node:assert/strict';
import test from 'node:test';
import { canvasGraph } from '../../../main/frontend/graph-explorer/graph-canvas-scope.ts';
import { routeDrawnEdges } from '../../../main/frontend/graph-explorer/graph-edge-routing.ts';
import { computeEdgePorts, edgeGeometry, edgePortKey, graphNodeSize, optimizeEdgeBends, quadraticPoint } from '../../../main/frontend/graph-explorer/graph-geometry.ts';
import { computeGraphLayout } from '../../../main/frontend/graph-explorer/graph-layout-engine.ts';
import { STATEMENT_LINK_EDGE_PREFIX } from '../../../main/frontend/graph-explorer/statement-links.ts';
import { badExportGraph, iri } from './fixtures/layout-demo-graph.mjs';

const curveOf = (graph, bends, edgeId) => {
  const byId = new Map(graph.nodes.map((node) => [node.id, node]));
  const ports = computeEdgePorts(graph.nodes, graph.edges);
  const edge = graph.edges.find((candidate) => candidate.id === edgeId);
  return edgeGeometry(byId.get(edge.source), byId.get(edge.target), bends.get(edgeId) ?? 0,
    ports.get(edgePortKey(edge.id, edge.source)), ports.get(edgePortKey(edge.id, edge.target)));
};

test('hidden values and classes never bend the drawn arrows', () => {
  // Hidden literals and classes sit exactly where the sane detours of Acme→Oslo and Acme→Widget would pass.
  const hidden = (name, kind) => kind === 'literal'
    ? { x: 260 + ((name.length * 37) % 400), y: 300 + ((name.length * 13) % 60) }
    : { x: 100 + ((name.length * 53) % 700), y: 330 };
  const graph = badExportGraph(hidden);
  const drawn = canvasGraph(graph, false);
  assert.equal(drawn.nodes.length, 10);
  const bends = routeDrawnEdges(graph, false, 3);
  assert.deepEqual([...bends].sort(), [...routeDrawnEdges(drawn, false, 3)].sort(), 'hidden cards changed the routing');
  const acmeOslo = `${iri('Acme')}|${iri('locatedIn')}|${iri('Oslo')}`;
  const curve = curveOf(drawn, bends, acmeOslo);
  const byId = new Map(drawn.nodes.map((node) => [node.id, node]));
  const length = Math.hypot(byId.get(iri('Oslo')).x - byId.get(iri('Acme')).x, byId.get(iri('Oslo')).y - byId.get(iri('Acme')).y);
  assert.ok(Math.abs(bends.get(acmeOslo)) <= length * 0.5, `Acme→Oslo bend ${bends.get(acmeOslo)} for length ${length}`);
  assert.ok(curve.control.y > Math.max(curve.start.y, curve.end.y), 'the detour must use the empty row below, not arc over Carol');
  assert.equal(routeDrawnEdges(graph, true, 3).size, 27, 'with Values on every edge is routed');
});

test('layout routing ignores the statement-link springs the app adds for reifiers', async () => {
  const node = (id, x, y) => ({ id, label: id, kind: 'iri', x, y });
  const graph = { revision: 1, nodes: [node('s', 0, 0), node('o', 300, 0), node('r', 150, 200)], edges: [
    { id: 'e', source: 's', target: 'o', predicate: 'urn:p', label: 'p' },
    { id: `${STATEMENT_LINK_EDGE_PREFIX}x:s`, source: 'r', target: 's', predicate: 'urn:reifies', label: 'reifies' },
    { id: `${STATEMENT_LINK_EDGE_PREFIX}x:o`, source: 'r', target: 'o', predicate: 'urn:reifies', label: 'reifies' },
  ] };
  const result = await computeGraphLayout(graph, { mode: 'network' });
  assert.deepEqual([...result.bends.keys()], ['e']);
  assert.equal(result.positions.size, 3);
});

const card = (id, x, y) => ({ id, label: id, kind: 'iri', x, y });
const link = (source, target) => ({ id: `${source}-${target}`, source, target, predicate: 'urn:p', label: 'p' });
function obstructedCards(graph, bends) {
  const byId = new Map(graph.nodes.map((node) => [node.id, node]));
  const ports = computeEdgePorts(graph.nodes, graph.edges);
  const hits = [];
  for (const edge of graph.edges) {
    const curve = edgeGeometry(byId.get(edge.source), byId.get(edge.target), bends.get(edge.id) ?? 0,
      ports.get(edgePortKey(edge.id, edge.source)), ports.get(edgePortKey(edge.id, edge.target)));
    for (const node of graph.nodes) {
      if (node.id === edge.source || node.id === edge.target) continue;
      const size = graphNodeSize(node);
      for (let i = 0; i <= 2000; i++) {
        const p = quadraticPoint(curve.start, curve.control, curve.end, i / 2000);
        if (Math.abs(p.x - node.x) < size.width / 2 + 2 && Math.abs(p.y - node.y) < size.height / 2 + 2) { hits.push(node.id); break; }
      }
    }
  }
  return hits;
}

test('a detour blocked by a second card is retried on the emptier side with the smallest bend that clears', () => {
  // Cards stacked above the corridor need a bend beyond the cap; below, one extra card (E) blocks the first small
  // detours but a ~210 bend clears everything. Today only the straight line's blocker (A) produces candidates.
  const graph = { revision: 1, nodes: [card('s', 0, 0), card('t', 600, 0), card('A', 300, 0), card('B', 300, -64), card('C', 300, -128),
    card('D', 300, -200), card('E', 300, 64)], edges: [link('s', 't')] };
  const bends = optimizeEdgeBends(graph.nodes, graph.edges, 2);
  assert.deepEqual(obstructedCards(graph, bends), [], `bend ${bends.get('s-t')}`);
  assert.ok(Math.abs(bends.get('s-t')) <= 600 * 0.75, `bend ${bends.get('s-t')} exceeds 0.75 × length`);
  const curve = curveOf(graph, bends, 's-t');
  assert.ok(curve.control.y > 0, `the clear side is below (control ${curve.control.y})`);
});

test('a corridor stacked on both sides is still cleared by a bend derived from the second blockers', () => {
  const stack = [];
  for (let i = 1; i <= 4; i++) stack.push(card(`up${i}`, 300, -64 * i), card(`down${i}`, 300, 64 * i));
  const graph = { revision: 1, nodes: [card('s', 0, 0), card('t', 600, 0), card('A', 300, 0), ...stack], edges: [link('s', 't')] };
  const bends = optimizeEdgeBends(graph.nodes, graph.edges, 2);
  assert.deepEqual(obstructedCards(graph, bends), [], `bend ${bends.get('s-t')}`);
  assert.ok(Math.abs(bends.get('s-t')) <= 600 * 1.25, `bend ${bends.get('s-t')} exceeds the cap`);
});

test('an arrow that only grazes the margin of a card stays straight when the only clear route is a wide arc', () => {
  // A's top edge is 5 px below the line (inside the 9 px margin, outside the card); any clearing detour must also pass
  // B above or C below, i.e. needs a bend of 200 px or more on a 600 px edge.
  const graph = { revision: 1, nodes: [card('s', 0, 0), card('t', 600, 0), card('A', 300, 28), card('B', 300, -40), card('C', 300, 110)], edges: [link('s', 't')] };
  const bends = optimizeEdgeBends(graph.nodes, graph.edges, 2);
  assert.equal(bends.get('s-t'), 0, `bend ${bends.get('s-t')}`);
  // Through the card body, the arc is still taken.
  const blocked = { ...graph, nodes: graph.nodes.map((node) => (node.id === 'A' ? { ...node, y: 10 } : node)) };
  assert.notEqual(optimizeEdgeBends(blocked.nodes, blocked.edges, 2).get('s-t'), 0);
});
